import os, glob, re

def load_grids():
    """Load all demo and test input grids from current session logs."""
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        print("RLM_SESSION_DIR not set")
        return {}

    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    try:
        with open(session_file, 'r') as f:
            content = f.read().replace('\n\n', '\n')
    except FileNotFoundError:
        print(f"Session file not found: {session_file}")
        return {}

    grids = {}
    for line in content.split('\n'):
        if '(Demo pair' in line or '(Test input)' in line:
            # Extract grid info
            match = re.search(r'Demo pair (\d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', line)
            if match:
                key = match.group(1)
                rows, cols = int(match.group(2)), int(match.group(3))
                # Get the grid from subsequent lines
                start_line = line
                grid_rows = []
                temp_line = 0
                end_pos = start_line
                while temp_line < rows:
                    temp_pos = content.find('\n', end_pos)
                    if temp_pos == -1:
                        break
                    temp_line += 1
                    end_pos = temp_pos + 1
                remaining = content[end_pos:].split('\n')[:rows]
                valid_grid = all(len(r) == cols and all(x.isdigit() for x in r.strip()) for r in remaining)
                if valid_grid:
                    grids[key] = [[int(x) for x in r.split()] for r in remaining]
    return grids

grids = load_grids()
