print(f"Total grids loaded: {len(grids)}")

import os, re

def load_grids():
    d = os.environ.get('RLM_SESSION_DIR', '')
    if not d:
        return {}
    basename = os.path.basename(d)
    session_file = os.path.join(d, '../../sessions', basename + '.jsonl')

    with open(session_file, 'r') as f:
        content = f.read()

    grids = {}
    lines = content.split('\n')
    i = 0
    while i < len(lines):
        line = lines[i]
        if '(Demo pair' in line or '(Test input)' in line or '(Input' in line:
            match = re.search(r'Demo pair (\d+ (?:input|output)|Test input|Input) \((\d+)x(\d+)\):\n', line)
            if match:
                key = match.group(1)
                rows, cols = int(match.group(2)), int(match.group(3))
                grid_rows = []
                j = i + 1
                while j < len(lines) and len(grid_rows) < rows:
                    grid_rows.append(lines[j].strip())
                    j += 1
                if all(len(r) == cols and all(x.isdigit() for x in r) for r in grid_rows):
                    grids[key] = [[int(x) for x in r] for r in grid_rows]
        i += 1
    return grids

grids = load_grids()
for k in sorted(grids.keys()):
    print(f"{k}: {grids[k]}")
print(f"\nTotal: {len(grids)} grids")

