import json

H, W = 25, 8
bg = 5

def transform_by_color(grid):
    output = [[bg]*W for _ in range(H)]

    # Get non-background cells as (r,c) -> color
    colored = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                colored[(r,c)] = grid[r][c]

    # Direction map
    color_dir = {
        2: (-1, 1),   # NE
        3: (-1, -1),  # NW  
        8: (1, 1)     # SE
    }

    for (r, c), color in colored.items():
        # First shift NW
        nr, nc = r - 1, c
        if 0 <= nr < H and 0 <= nc < W:
            output[nr][nc] = color

        # Then shoot in color-specific direction
        if color in color_dir:
            dr, dc = color_dir[color]
            tr, tc = nr + dr, nc + dc
            # Ray length = color value
            for _ in range(color):
                if 0 <= tr < H and 0 <= tc < W:
                    output[tr][tc] = max(output[tr][tc], color)
                    tr += dr
                    tc += dc

    return output

