H, W = 25, 8
bg = 5

def transform_blocked_shoot(grid):
    """
    Process by color priority (low to high)
    Each cell shoots in color direction, blocking lower value colors
    Lower values claim positions they can reach, then higher can't overwrite
    """
    output = [[bg]*W for _ in range(H)]

    colored = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                colored[(r,c)] = grid[r][c]

    # Directions
    color_dirs = {
        2: (-1, 1),  # NE
        3: (-1, -1), # NW
        8: (1, 1)    # SE
    }

    # Process low color first (so they claim positions)
    for color in sorted(colored.values()):
        for (r, c), ccolor in colored.items():
            if ccolor == color:
                # Shift NW
                nr, nc = r - 1, c
                if 0 <= nr < H and 0 <= nc < W:
                    output[nr][nc] = color

                # Shoot ray if direction known
                if ccolor in color_dirs:
                    dr, dc = color_dirs[ccolor]
                    tr, tc = nr + dr, nc + dc
                    for step in range(ccolor):
                        if 0 <= tr < H and 0 <= tc < W:
                            if output[tr][tc] == bg or output[tr][tc] == color:
                                output[tr][tc] = color
                            # Don't overwrite higher values
                        tr += dr
                        tc += dc
            # Else: higher color, already claimed? or skip

    return output

