def transform_turn_north(grid):
    """2 shoots NE, but if column >= W-2, shoot NORTH instead"""
    output = [[bg]*W for _ in range(H)]

    colored = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                colored[(r,c)] = grid[r][c]

    color_dirs = {
        2: (-1, 1),  # NE
        3: (-1, -1), # NW
        8: (1, 1)    # SE
    }

    for color in sorted(colored.values()):
        for (r, c), ccolor in colored.items():
            if ccolor == color:
                nr, nc = r - 1, c
                if 0 <= nr < H and 0 <= nc < W:
                    output[nr][nc] = color

                if ccolor in color_dirs:
                    dr, dc = color_dirs[ccolor]
                    tr, tc = nr + dr, nc + dc

                    for step in range(ccolor):
                        if 0 <= tr < H and 0 <= tc < W:
                            # For 2: at column W-2 or more, change direction to NORTH
                            if ccolor == 2 and tc >= W-2:
                                dr, dc = -1, 0  # Change to NORTH
                                print(f"  Changed 2 direction at ({tr},{tc}) from NE to N")

                            if output[tr][tc] == bg or output[tr][tc] == color:
                                output[tr][tc] = color

                            tr += dr
                            tc += dc

    return output

